  [7069] = { "周囲のパーティーメンバーが与えるPhysicalダメージを$N1増加させます。プレイヤーは一度に、パラディン一人につき一つのオーラしか受けられません。オーラはキャンセルするまで持続します。", "与える物理ダメージが$N1増加しています。", 0x683231ad, 0x422f867d, "uu" },
