  [7093] = { "敵を威嚇し、$D1の間恐怖で逃げ出させます。一度に恐怖させられる対象は1体だけです。", "恐怖で逃げ惑っています。", 0x397f36db, 0xfa67e4a8, "uu" },
  [7098] = { "敵に$D1の間呪いをかけ、攻撃時に$N2%の確率でその攻撃対象の体力を$N3回復させるようにします。", "命中時に$N1%の確率で敵の目標を回復させます。", 0xc5288a75, 0xbfc0170d, "uu" },
  [7101] = { "敵に$N1のFireダメージを与えます。", nil, 0xb324eff3, nil, "um" },
  [7102] = { "敵の攻撃間隔を$N1%、詠唱時間を$N2%延ばし、さらに攻撃を受けた際に$N3%の確率で味方に感染を広めるようにします。効果時間は$D1です。", "攻撃間隔が$N1%長くなっています。\n詠唱速度が$N2%低下しています。\n攻撃を受けると$N3%の確率で味方に伝染病を広めます。", 0x6495f09b, 0x447aa966, "uu" },
  [7103] = { nil, "攻撃間隔が$N1%長くなっています。\n詠唱速度が$N2%低下しています。\n攻撃を受けると$N3%の確率で味方に伝染病を広めます。", nil, 0x447aa966, "mu" },
