  [7125] = { "$D1ごとに敵に$N1のNatureダメージを与えます。さらに$D2ごとにマナを$N3吸い取り、術者に移します。効果時間は$D3です。", "$D1ごとに$N1のNatureダメージを受けています。\n$D2ごとにマナを$N3吸い取られています。", 0x45485166, 0x0b3ee95f, "uu" },
