  [7294] = { "$N2ヤード以内のパーティメンバーを攻撃したクリーチャーに$N1のHolyダメージを与えます。プレイヤーが受けられるAuraは、パラディン1人につき一度に1つだけです。", "攻撃してきた相手すべてに$N1のHolyダメージを与えます。", 0x491f2ea9, 0x506b4a8f, "uu" },
  [7295] = { "$D1の間敵を動けなくし、体力を$N2吸収して術者に移します。", "移動できません。", 0xd0fdc3db, 0x18deeb81, "uu" },
  [7300] = { "アーマーを$N1増加させます。術者を攻撃した敵は、$D1の間、移動速度が$N2%低下し、攻撃間隔が$N3%延びることがあります。メイジが一度に使えるアーマー呪文は1種類だけです。効果時間は$D2です。", "アーマーが$N1増加し、攻撃者を減速させることがあります。", 0xc9cf58c7, 0xe901b2ed, "uu" },
  [7301] = { "アーマーを$N1増加させます。術者を攻撃した敵は、$D1の間、移動速度が$N2%低下し、攻撃間隔が$N3%延びることがあります。メイジが一度に使えるアーマー呪文は1種類だけです。効果時間は$D2です。", "アーマーが$N1増加し、攻撃者を減速させることがあります。", 0xc9cf58c7, 0xe901b2ed, "uu" },
  [7302] = { "アーマーを$N1、冷気への抵抗力を$N2上げます。術者を攻撃した敵は、$D1の間、移動速度が$N3%低下し、攻撃間隔が$N4%長くなることがあります。メイジにかけられるアーマー呪文は同時に一種類だけです。効果時間は$D2です。", "アーマーが$N1、Frost耐性が$N2上昇し、攻撃者を減速させることがあります。", 0x66634630, 0x7ddffa1a, "uu" },
  [7320] = { "アーマーを$N1、Frostへの抵抗力を$N2上げます。敵が術者を攻撃すると、$D1の間、その敵の移動速度が$N3%低下し、攻撃間隔が$N4%延びることがあります。メイジに同時にかけられるアーマー呪文は1種類だけです。効果時間は$D2です。", "アーマーが$N1、Frost耐性が$N2上昇し、攻撃者を減速させることがあります。", 0x66634630, 0x7ddffa1a, "uu" },
  [7321] = { nil, "移動速度が$N1%低下し、攻撃間隔が$N2%長くなっています。", nil, 0x393b75e9, "mu" },
  [7322] = { "敵に冷気の矢を放ち、$N1のFrostダメージを与え、$D1の間移動速度を$N2%低下させます。", "移動速度が$N1%低下しています。", 0x0ea2143b, 0xbe1d3d24, "uu" },
  [7327] = { "Seal of Wisdom（Rank 1）を習得します。", nil, 0x47359eca, nil, "um" },
  [7328] = { "死んでいる味方を、体力$N1及びマナ $N2の状態で生き返らせます。戦闘中は使用できません。", nil, 0xf0621701, nil, "um" },
  [7331] = { "パラディンと周囲のグループメンバーの体力を、ティックごとに$N1回復します。", nil, 0x5b9cc6dd, nil, "um" },
  [7342] = { "術者の前方の円錐範囲にいる敵に通常ダメージに加えて$N1を与えます。", nil, 0xe5bf1e4e, nil, "um" },
  [7353] = { "精神が$N1増加します。", "精神が$N1増加します。", 0x48f21010, 0x7e8fc3e9, "uu" },
  [7357] = { "$D2の間、$D1ごとに敵に$N1のNatureダメージを与え、攻撃間隔を$N3%延ばし、移動を$N4%遅くします。", "$D1ごとに$N1のNatureダメージを受けています。\n攻撃間隔が$N3%長くなっています。\n移動速度が$N4%低下しています。", 0x8d9a5a91, 0x5c128d7f, "uu" },
  [7358] = { "精神が$N1増加します。", "精神が$N1増加します。", 0x48f21010, 0x7e8fc3e9, "uu" },
  [7359] = { "焚き火を作り、近くにいる者の精神を8上げ、料理ができるようにします。", nil, 0xe838f265, nil, "um" },
  [7363] = { "近くのパーティメンバーの精神を$N1上げます。", nil, 0x23ae3f5e, nil, "um" },
  [7365] = { "敵に毒の瓶を投げつけ、$D2の間、$D1ごとに$N1のNatureダメージを与えます。", "$D1ごとに$N1のNatureダメージを受けています。", 0x5f267b87, 0xf6322bec, "uu" },
  [7366] = { "攻撃的な構えをとり、ウォリアーが敵を攻撃すると怒りを生み出します。効果時間は$D1です。", nil, 0x10d29728, nil, "um" },
  [7367] = { "$D2の間、$D1ごとに敵に$N1のNatureダメージを与え、受けるPhysicalダメージを$N3増加させます。", "$D1ごとに$N1のNatureダメージを受けています。\n受ける物理ダメージが$N3増加しています。", 0x72b5dc85, 0x4ee0a8ee, "uu" },
  [7369] = { "対象と近くにいるもう一体の敵に、武器ダメージに加えて$N1のダメージを与えるなぎ払い攻撃です。", nil, 0xdd419f36, nil, "um" },
  [7371] = { "敵に突撃し、$D1の間動けなくして、イノシシの次の攻撃の近接攻撃力を$N2上げます。", nil, 0xcc44b4da, nil, "um" },
  [7372] = { "敵を痛めつけて$N1のダメージを与え、$D1の間、敵の移動速度を$N2%下げます。", "移動速度が$N1%低下しています。", 0x99e679bf, 0xbd9449c1, "uu" },
  [7373] = { "敵を痛めつけて$N1のダメージを与え、$D1の間、敵の移動速度を$N2%下げます。", "移動速度が$N1%低下しています。", 0x99e679bf, 0xbd9449c1, "uu" },
  [7376] = { "あらゆる被ダメージを$N1%減少させます。与えるダメージが$N2%減少します。\n生み出すすべての脅威が$N3%増加します。", nil, 0xbb4e7c90, nil, "um" },
  [7379] = { "即座に敵に反撃し、$N1のダメージと大量の脅威を与えます。Revengeはブロック、回避、受け流しの後にのみ使用できます。", nil, 0x3c5ac9a7, nil, "um" },
  [7381] = { "クリティカル率を$N1%上げます。受けるすべてのダメージが$N2%増加します。", nil, 0x438c317e, nil, "um" },
  [7383] = { nil, "Physicalダメージに対する免疫があります。", nil, 0xe9f5cca7, "mu" },
  [7384] = { "即座に敵を圧倒し、武器ダメージに$N1を加えたダメージを与えます。対象が回避した後にのみ使用できます。Overpowerはブロック、回避、受け流しされません。", nil, 0x8be488f4, nil, "um" },
  [7386] = { "対象のアーマーを削り、Sunder Armorごとに$N1下げ、大量の脅威を発生させます。最大5回まで重ねられます。効果時間は$D1です。", "アーマーが$N1低下しています。", 0x03bf3c06, 0x57b604c7, "uu" },
  [7389] = { "$D1の間、術者のペットの攻撃速度を$N1%増加させます。", "攻撃速度が$N1%上昇しています。", 0xadfbf982, 0x8859e2db, "uu" },
  [7393] = { "対象の体力を$N1回復します", nil, 0x4ddf02fb, nil, "um" },
  [7394] = { "周囲の敵に通常ダメージに加えて$N1を与えます。", nil, 0x301ad2a4, nil, "um" },
  [7395] = { "選択した範囲のすべての敵に$N1のFireダメージを与えます。", nil, 0xee6c0689, nil, "um" },
  [7396] = { "$D1の間、攻撃速度を$N1%上昇させます。", "攻撃速度が上昇しています。", 0x7e4b2c7f, 0x778d86da, "uu" },
  [7399] = { "敵を恐怖させ、$D1の間恐怖で逃げ出させます。一度に恐怖させられる対象は1体だけです。", "恐怖で逃げ惑っています。", 0x69bf89ab, 0xfa67e4a8, "uu" },
  [7400] = { "$N1のダメージと中程度の脅威を与え、$D1の間、対象の攻撃を自分に集中させる挑発的な攻撃です。", "挑発されています。", 0x8506dcc4, 0x36f56123, "uu" },
  [7402] = { "$N1のダメージと中程度の脅威を与え、$D1の間、対象の攻撃を自分に集中させる挑発的な攻撃です。", "挑発されています。", 0x8506dcc4, 0x36f56123, "uu" },
  [7405] = { "対象のアーマーを削り、Sunder Armorごとに$N1下げ、大量の脅威を発生させます。最大5回まで重ねられます。効果時間は$D1です。", "アーマーが$N1低下しています。", 0x03bf3c06, 0x57b604c7, "uu" },
